import{_ as t,o as a,c as l,a2 as n}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"MultiPlanet","description":"","frontmatter":{"title":"MultiPlanet","order":11},"headers":[],"relativePath":"mods/multiplanet.md","filePath":"mods/multiplanet.md","lastUpdated":1786957039000}'),o={name:"mods/multiplanet.md"};function i(r,e,s,d,u,p){return a(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="multiplanet" tabindex="-1">MultiPlanet <a class="header-anchor" href="#multiplanet" aria-label="Permalink to &quot;MultiPlanet&quot;">​</a></h1><blockquote><p>Unlocks the planet count limit for MultiPlanet events in <em>A Dance of Fire and Ice</em>, supporting <strong>2–8 planets</strong> (official limit is 2–3).</p><p>Project: <a href="https://github.com/adofaiex/MultiPlanet" target="_blank" rel="noreferrer">https://github.com/adofaiex/MultiPlanet</a></p></blockquote><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li>✅ Unlocks the <code>planets</code> property of MultiPlanet events, supporting 2–8 planets</li><li>✅ Use a slider in the editor to adjust planet count (range 2–8)</li><li>✅ New MultiPlanet events auto-reset <code>planets</code> to 2 (avoids inheriting the previous event&#39;s value)</li><li>✅ Removes the editor warning for &gt;3 planets</li><li>✅ Removes the hardcoded runtime limit</li><li>🆕 <strong>Level converter</strong>: convert any level to a multi-planet version (2–8 planets)</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li><p>Make sure <a href="https://www.nexusmods.com/site/mods/21" target="_blank" rel="noreferrer">Unity Mod Manager</a> is installed and ADOFAI mod support is enabled</p></li><li><p>Copy <code>MultiPlanet.dll</code> and <code>Info.json</code> to:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>\\A Dance of Fire and Ice\\Mods\\MultiPlanet\\</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>Launch the game and enable MultiPlanet in the Mod list</p></li></ol><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><h3 id="using-the-multiplanet-event" tabindex="-1">Using the MultiPlanet Event <a class="header-anchor" href="#using-the-multiplanet-event" aria-label="Permalink to &quot;Using the MultiPlanet Event&quot;">​</a></h3><ol><li>Open the level editor</li><li>Add a <strong>MultiPlanet</strong> event to any track</li><li>In the properties panel, <code>planets</code> now shows as a <strong>slider</strong> (or number input), adjustable 2–8</li></ol><h3 id="level-converter" tabindex="-1">Level Converter <a class="header-anchor" href="#level-converter" aria-label="Permalink to &quot;Level Converter&quot;">​</a></h3><p>Convert any level to a multi-planet version (2–8 planets).</p><blockquote><p>📝 Detailed converter steps to be supplemented.</p></blockquote><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><blockquote><p>📝 To be supplemented (feel free to report in the repository Issues)</p></blockquote>',14)])])}const m=t(o,[["render",i]]);export{h as __pageData,m as default};
